#!/usr/bin/env python3
"""Apply verified V132→V133 minimal patch with exact source-hash safety."""
import base64,subprocess,sys,zlib
from pathlib import Path
ROOT=Path(__file__).resolve().parent.parent
BASE="9987b17d2e5fc8b3aff74376ffaa8041d5100168"
TARGET="166a031407c2174f7903a338ad8f6add75258234"
PATCH=""
def sha():
    return subprocess.check_output(["git","hash-object","app.py"],cwd=ROOT,text=True).strip()
def main():
    current=sha()
    if current==TARGET:
        print("Already V133");return
    if current!=BASE:
        raise SystemExit("Refusing to patch unexpected app.py source: "+current)
    patch=zlib.decompress(base64.b64decode(PATCH)).decode("utf-8")
    for args in [["git","apply","--check","--unidiff-zero"],["git","apply","--unidiff-zero"]]:
        subprocess.run(args,cwd=ROOT,input=patch,text=True,check=True)
    if sha()!=TARGET:raise SystemExit("V133 SHA mismatch")
    subprocess.run([sys.executable,"-m","py_compile","app.py"],cwd=ROOT,check=True)
    print("V133 generated and verified")
if __name__=="__main__":main()
